{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_29",
      "quote": "The meta-analytic findings highlight substantial gaps in the reporting of psychometric properties across the literature. A considerable proportion of studies (39%) did not report any psychometric information, meaning that the meta-analytic results were necessarily based on a subset of studies. ... Evidence on reliability and validity, particularly discriminant validity and test-retest reliability, remains largely derived from adult populations and questionnaire-based measures [26, 28, 33, 224], with comparatively limited data available for behavioral observations and physiological measures in children.",
      "reason": "The manuscript explicitly describes the current state of knowledge and several important uncertainties/gaps (e.g., substantial non-reporting of psychometric properties, reliance on adult/questionnaire evidence, limited data for behavioral and physiological measures)."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_2",
      "quote": "Valid and reliable ER measures are needed to develop models for mental health promotion and treatment. This systematic review provides a comprehensive overview of ER behavioral observation and physiological measures of children and adolescents, including their theoretical embedding and psychometric properties.",
      "reason": "The abstract states the importance and need for the review (need for valid/reliable ER measures and providing a comprehensive overview), thus explaining why the review was conducted."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No retrieved evidence describes existing similar systematic reviews or explains the need for the current review relative to prior reviews; no citations or statements about updates/replications were found in the provided text."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The review concerns measurement methods for emotion regulation (behavioral and physiological measures), not intervention effects; thus a mechanism of action for an intervention is not applicable."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The review does not evaluate complex interventions or delivery contexts, so a logic model of intervention components and outcomes is not applicable."
    }
  ],
  "confidence": "85"
}

{
  "item_id": "PRISMA_2020_4",
  "elements": [
    {
      "element_id": "prisma_2020_4_e1",
      "status": "PRESENT",
      "chunk_id": "text_14",
      "quote": "The primary outcome was the reporting of psychometric properties in behavioral and physiological ER measures.",
      "reason": "The manuscript explicitly states the primary outcome of the review, which constitutes an explicit statement of the review's objective/question (i.e., to assess reporting of psychometric properties in behavioral and physiological ER measures)."
    },
    {
      "element_id": "prisma_2020_4_e2",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_7",
      "quote": "Studies were included according to the PICOS criteria [177]. Eligible studies included participants from birth to 15 years and 11 months. Studies were required to use at least one ER measurement and report ER as an outcome variable. Both studies with and without group comparisons were eligible.",
      "reason": "The review addresses measurement and reporting of emotion regulation outcomes rather than effects of interventions; the inclusion criteria permit studies with and without group comparisons, indicating this is not a review of intervention effects requiring PICO-formulated planned comparisons."
    }
  ],
  "confidence": 80
}

{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PRESENT",
      "chunk_id": "text_7",
      "quote": "Studies were included according to the PICOS criteria [177]. Eligible studies included participants from birth to 15 years and 11 months. Studies were required to use at least one ER measurement and report ER as an outcome variable. Both studies with and without group comparisons were eligible. No language restrictions were applied; studies in all languages were included. We initially preregistered an age range of 0 to 18 years. However, this age range was reduced to 0 to 15 years and 11 months due to the large number of eligible records identified. Studies reporting on secondary literature (e.g. meta-analyses, reviews) were excluded.",
      "reason": "The chunk explicitly lists key study-level eligibility characteristics: age range, requirement to use an ER measurement and report ER as outcome, inclusion of studies with/without group comparisons, and exclusion of secondary literature; it states inclusion followed PICOS."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PARTIAL",
      "chunk_id": "text_7",
      "quote": "No language restrictions were applied; studies in all languages were included.",
      "reason": "Language eligibility is explicitly stated (no restrictions). However, dissemination year and explicit publication/report status eligibility criteria are not clearly specified in the eligibility statement; while results and tables (table_9) show publication types and the results mention years of included studies, the protocol does not explicitly state year limits or formal publication-status inclusion/exclusion rules."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "PARTIAL",
      "chunk_id": "text_12",
      "quote": \"Other exclusions were based on ineligible age groups, absence of an ER outcome measure, secondary data, or insufficient detail on ER measurement.\",
      "reason": "The manuscript explicitly notes exclusion for 'absence of an ER outcome measure' and for 'insufficient detail on ER measurement', which differentiates some cases; however, it does not explicitly state whether studies were excluded because outcomes were measured but outcome results were not reported. Thus the distinction is only partially addressed."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PARTIAL",
      "chunk_id": "text_2",
      "quote": \"This systematic review provides a comprehensive overview of ER behavioral observation and physiological measures of children and adolescents, including their theoretical embedding and psychometric properties... Measurement types, theoretical grounding, and psychometric properties (reliability, validity, objectivity) were extracted and compared across age groups using descriptive statistics and chi-square tests.\",
      "reason": "The review specifies key groupings used in syntheses (measurement types: behavioral observation vs physiological; comparisons across age groups) and indicates statistical comparisons were made. However, it does not fully and explicitly link every group used in each synthesis to the predefined comparisons in the review objectives or provide a comprehensive list of synthesis groups."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "PRESENT",
      "chunk_id": "text_7",
      "quote": \"We initially preregistered an age range of 0 to 18 years. However, this age range was reduced to 0 to 15 years and 11 months due to the large number of eligible records identified.\",
      "reason": "A clear rationale is provided for a notable restriction on study eligibility (reducing the age range) with the reason (large number of eligible records)."
    }
  ],
  "confidence": "85"
}

